const protected = new Proxy({ name: "Hariom", secret: "xyz" }, {
  deleteProperty(target, prop) {
    if (prop === "secret") return false
    delete target[prop]
    return true
  }
})
delete protected.name
try { delete protected.secret } catch(e) {}
return { hasName: "name" in protected, hasSecret: "secret" in protected }
